import { useEffect, useRef, useState } from "react";
import { useAuth } from "./Auth";
import { api, displayValue, id } from "./api";
import { Field } from "./App";
import type { Connection, ConnectionEditorSection, SourceBrowseEntry, SourceBrowsePage, SourceConnectionType, SourceImportPoint, SourceImportPreview, SourceLimits, SourceMqttMapping, SourceOwnedPoint, SourcePoint, SourceReadValue, SourceScriptTestResult, SourceSettings, TagDefinition, TagWriteDataType } from "./types";
import { modelFromSource, openModelDraft } from "./modelWorkspace";
import { scalarTypes } from "./deviceConnections";
import { defaultSourceSettings, parseSourceMap, sourceBrowseRows, sourceEntryKey, sourceImportPoint, validateSourcePoints } from "./sourceConnections";
import "./sourceConnections.css";

const errorMessage = (error: unknown) => error instanceof Error ? error.message : String(error);
function SourceScriptTestOutput({ result }: { result: SourceScriptTestResult }) {
  return <><p>Elapsed {Number.isFinite(result.elapsedMs) ? `${result.elapsedMs.toFixed(2)} ms` : "not reported"} · Structured updates: {result.structuredUpdates === "patch" ? "Patch · omitted leaves retain their values" : result.structuredUpdates === "snapshot" ? "Snapshot · omitted leaves become NoData" : "not reported"}</p><pre className="source-test-result" role="status">{JSON.stringify(result, null, 2)}</pre></>;
}
const defaults: Required<SourceLimits> = { documentBytes: 1048576, valueBytes: 65536, stateBytes: 16777216, queueBytes: 8388608, queueCount: 4096, packetBytes: 278528, payloadBytes: 262144, catalogCount: 10000, catalogBytes: 8388608, requestTimeoutMs: 2000, operationTimeoutMs: 10000, connectTimeoutMs: 5000, decodeNodes: 65536, decodeBytes: 33554432, scriptTimeoutMs: 100, scriptResultBytes: 262144, scriptResultDepth: 16, scriptResultMembers: 4096, scriptResultLeaves: 1024, workerCount: 2 };
const limitLabels: Record<keyof SourceLimits, string> = { documentBytes: "HTTP / XML document bytes", valueBytes: "Bytes per value", stateBytes: "Canonical state bytes", queueBytes: "Ingress queue bytes", queueCount: "Pending input records", packetBytes: "MQTT packet bytes", payloadBytes: "MQTT payload bytes", catalogCount: "Catalog entries", catalogBytes: "Catalog metadata bytes", requestTimeoutMs: "Request timeout (ms)", operationTimeoutMs: "User operation timeout (ms)", connectTimeoutMs: "Connect timeout (ms)", decodeNodes: "Decoded nodes", decodeBytes: "Decode working bytes", scriptTimeoutMs: "Script deadline (ms)", scriptResultBytes: "Script result bytes", scriptResultDepth: "Script result depth", scriptResultMembers: "Script result members", scriptResultLeaves: "Script result leaves", workerCount: "Script workers" };
const limitHints: Partial<Record<keyof SourceLimits, string>> = {
  documentBytes: "Maximum decoded HTTP response or XML document size. 1048576 is 1 MiB; oversized documents are rejected, not partially imported.",
  valueBytes: "Maximum encoded size of one accepted value, including JSON stored as text. 65536 is 64 KiB.",
  stateBytes: "Memory budget for the connection's reduced current values. 16777216 is 16 MiB; this is not a history retention setting.",
  queueBytes: "Byte ceiling for subscription-sync input and individual event-stream messages, also bounded by the document limit. 8388608 is 8 MiB; oversized input is rejected.",
  queueCount: "Maximum update records accepted from subscription-sync or event-stream input, not a tag count. The default is 4096.",
  catalogCount: "Maximum discovered metadata entries kept for browsing. The default is 10000; a truncated catalog is reported before import.",
  catalogBytes: "Memory budget for discovered names, types and other browse metadata. 8388608 is 8 MiB.",
  requestTimeoutMs: "Deadline for an ordinary source request. 2000 means 2 seconds; this is not the polling interval or the lifetime of a stream.",
  operationTimeoutMs: "Deadline for a user operation such as testing, browsing or reading. 10000 means 10 seconds.",
  connectTimeoutMs: "Time allowed to establish a transport connection or open a stream. 5000 means 5 seconds.",
  decodeNodes: "Maximum XML / JSON nodes processed while decoding input. The default is 65536; deeply nested or very large input may be rejected.",
  decodeBytes: "Temporary working-memory budget while decoding input, separate from saved current values. 33554432 is 32 MiB.",
};
const tlsHints = {
  caCertificateReference: "Name of an existing gateway CA certificate reference for a private certificate authority. Leave blank to use the gateway's normal trust store; do not paste a certificate or file path.",
  clientCertificateReference: "Existing gateway certificate reference used to identify this client when the service requires mutual TLS. Leave blank for ordinary server-only HTTPS.",
  clientKeyReference: "Existing gateway private-key reference paired with the client certificate. Leave blank if the certificate reference already includes its private key.",
  serverCertificateSha256: "Optional exact server-certificate fingerprint: 64 hexadecimal characters supplied by the service owner. Uses the pin instead of certificate-chain trust; hostname and validity checks still apply. A changed certificate requires an updated pin.",
};

export function SourceConnectionFields({ type, source, onChange, savedMappingIds = [], section }: { type: SourceConnectionType; source?: SourceSettings; onChange: (source: SourceSettings) => void; savedMappingIds?: string[]; section?: ConnectionEditorSection }) {
  const settings = source ?? defaultSourceSettings(type), auth = settings.authentication ?? { mode: "none" as const };
  const patch = (next: Partial<SourceSettings>) => onChange({ ...settings, ...next });
  return <div className="source-connection-fields">
    <div className="source-field-section" hidden={section !== undefined && section !== "connection"}>
    <p className="muted">Read-only acquisition. Source status, source timestamps and gateway receipt times are tracked separately.</p>
    {type !== "mqtt" && <div className="source-mapping-guide"><p>{type === "mtconnect" ? "Connect to the machine's MTConnect agent, then select the observations you want as tags. Start with Polling and leave the filters empty for your first test." : "Connect to the i3X API, then select element values you want as tags. Start with Polling and one known value before trying subscriptions."} Save and test the connection, then use <strong>Browse source → Preview point and tag import → Apply reviewed import</strong> to save points and create tags together.</p><a href={`https://sparkstudiox.com/docs/${type === "mtconnect" ? "mtconnect" : "i3x"}-setup/#connection-field-reference`} target="_blank" rel="noreferrer">{type === "mtconnect" ? "MTConnect" : "i3X"} setup and field guide ↗</a></div>}
    <Field label={type === "mqtt" ? "Broker endpoint" : "Base URL"} hint={type === "mqtt" ? "mqtt://, mqtts://, ws:// or wss://; keep credentials in Authentication." : type === "i3x" ? "Complete i3X 1.0 API root, such as https://i3x.example.com/v1. Include /v1 when required, not an element or current-value URL. HTTPS is required outside loopback; authentication is optional." : "MTConnect 2.5–2.8 agent root, such as http://agent.example.com:5000. Do not append /probe, /current or /sample; the connector adds those paths. The gateway must be able to reach this address."}><input value={settings.endpoint} onChange={event => patch({ endpoint: event.target.value })} /></Field>
    </div>
    <div className="source-field-section" hidden={section !== undefined && section !== (type === "mqtt" ? "connection" : "acquisition")}>
    <div className="form-two-col"><Field label="Acquisition" hint={type === "mqtt" ? undefined : type === "mtconnect" ? "Polling repeatedly requests current values. Subscription / stream follows the agent's sample updates and reduces them to current values. Start with Polling to verify setup." : "Polling repeatedly retrieves selected current values. Subscription / stream creates an i3X subscription and uses events or synchronization, with periodic current-state refreshes. Start with Polling."}><select disabled={type === "mqtt"} value={type === "mqtt" ? "subscribe" : settings.acquisition ?? "poll"} onChange={event => patch({ acquisition: event.target.value as "poll" | "subscribe" })}><option value="poll">Polling</option><option value="subscribe">Subscription / stream</option></select></Field><Field label={type === "mqtt" ? "Delivery" : "Poll / sync interval (ms)"} hint={type === "mqtt" ? undefined : settings.acquisition !== "subscribe" ? "Wait between current-value polling cycles. 1000 means 1 second; allowed range is 1000–60000 ms. This applies to the whole connection, not a separate timer per tag." : type === "mtconnect" ? "Requested sample-stream delivery interval. 1000 means 1 second; allowed range is 1000–60000 ms. This is not a value freshness deadline." : "Wait between subscription-sync requests when events are not used. 1000 means 1 second; allowed range is 1000–60000 ms. The reconciliation interval below is a separate current-state refresh."}>{type === "mqtt" ? <input readOnly value="Connection-owned subscription" /> : <input type="number" min={1000} max={60000} value={settings.intervalMs ?? 1000} onChange={event => patch({ intervalMs: Number(event.target.value) })} />}</Field></div>
    </div>
    <div className="source-field-section" hidden={section !== undefined && section !== "security"}>
    <h3 className="form-section-title">Authentication</h3>
    <Field label="Authentication mode" hint={type === "mqtt" ? undefined : "Choose None if the service does not require credentials. Otherwise match the service owner's instructions: HTTP username/password, Bearer token, or a key in a dedicated API-key header. Put credentials here, not in the Base URL."}><select value={auth.mode} onChange={event => patch({ authentication: { ...auth, mode: event.target.value as typeof auth.mode } })}><option value="none">None</option><option value="basic">Username and password</option>{type !== "mqtt" && <><option value="bearer">Bearer token</option><option value="api-key">API key</option></>}</select></Field>
    {auth.mode === "basic" && <div className="form-two-col"><Field label="Username" hint={type === "mqtt" ? undefined : "Service account name supplied by the service owner, with permission to browse and read the required values."}><input autoComplete="off" value={auth.username ?? ""} onChange={event => patch({ authentication: { ...auth, username: event.target.value } })} /></Field><Field label="Password" hint={auth.hasPassword ? "A protected password is saved. Leave unchanged to retain it; Clear removes it." : "Password for the service account. Stored protected on this gateway."}><input type="password" autoComplete="new-password" value={auth.password ?? ""} placeholder={auth.hasPassword ? "Saved password" : ""} onChange={event => patch({ authentication: { ...auth, password: event.target.value } })} />{auth.hasPassword && <button className="button small" onClick={() => patch({ authentication: { ...auth, password: null, hasPassword: false } })}>Clear password</button>}</Field></div>}
    {(auth.mode === "bearer" || auth.mode === "api-key") && <div className="form-two-col"><Field label={auth.mode === "api-key" ? "API key" : "Bearer token"} hint={auth.hasToken ? "A protected token is saved; leave unchanged to retain it. Clear removes it." : auth.mode === "api-key" ? "Key value supplied by the service owner. Sent in the API-key header below and stored protected on this gateway." : "Token value supplied by the service owner, without the Bearer prefix. Sent as an Authorization bearer token and stored protected on this gateway."}><input type="password" autoComplete="new-password" value={auth.token ?? ""} placeholder={auth.hasToken ? "Saved token" : ""} onChange={event => patch({ authentication: { ...auth, token: event.target.value } })} />{auth.hasToken && <button className="button small" onClick={() => patch({ authentication: { ...auth, token: null, hasToken: false } })}>Clear token</button>}</Field>{auth.mode === "api-key" && <Field label="API-key header" hint="Name of the HTTP header carrying the key, such as X-API-Key. Match the service's required name; this field is not the key value or an Authorization header."><input value={auth.header ?? "X-API-Key"} onChange={event => patch({ authentication: { ...auth, header: event.target.value } })} /></Field>}</div>}
    <details><summary>Certificates and server identity</summary><p className="muted">Enter existing gateway certificate references. Private keys and certificate contents are not embedded in connection settings.</p><div className="form-two-col">{([ ["caCertificateReference", "Trusted CA certificate reference"], ["clientCertificateReference", "Client certificate reference"], ["clientKeyReference", "Client private-key reference"], ["serverCertificateSha256", "Server certificate SHA-256 pin"] ] as const).map(([key, label]) => <Field key={key} label={label} hint={type === "mqtt" ? undefined : tlsHints[key]}><input value={settings.tls?.[key] ?? ""} onChange={event => patch({ tls: { ...settings.tls, [key]: event.target.value || null } })} autoComplete="off" /></Field>)}</div></details>
    </div>
    {type === "mtconnect" && <section className="source-mapping-section" aria-label="MTConnect filters and streaming" hidden={section !== undefined && section !== "acquisition"}><h3 className="form-section-title">Agent filters and stream</h3><p className="source-mapping-help">Filters choose which agent observations are available to browse and read. Heartbeat and sample count apply only to Subscription / stream.</p><div className="form-two-col"><Field label="Device filter" hint="Optional device name or identifier recognized by the agent, such as Mill01. Leave blank to include all devices. The filter applies to probe, current and sample requests."><input value={settings.mtConnect?.device ?? ""} onChange={event => patch({ mtConnect: { ...settings.mtConnect, device: event.target.value || null } })} /></Field><Field label="XPath filter" hint="Optional agent XPath selecting data items, such as //DataItem. Leave blank to include all items allowed by the device filter. This filters the agent's XML; it is not a point selector or tag path."><input value={settings.mtConnect?.path ?? ""} onChange={event => patch({ mtConnect: { ...settings.mtConnect, path: event.target.value || null } })} /></Field><Field label="Heartbeat (ms)" hint="Streaming only. Ask the agent to send a heartbeat when observations are quiet. 10000 means 10 seconds; allowed range is 1000–60000 ms. It keeps the stream observable, not the machine value fresh."><input type="number" min={1000} max={60000} value={settings.mtConnect?.heartbeatMs ?? 10000} onChange={event => patch({ mtConnect: { ...settings.mtConnect, heartbeatMs: Number(event.target.value) } })} /></Field><Field label="Observations per sample" hint="Streaming only. Maximum observations requested per sample document, not the number of tags or the polling interval. Start with 1000; allowed range is 1–10000."><input type="number" min={1} max={10000} value={settings.mtConnect?.count ?? 1000} onChange={event => patch({ mtConnect: { ...settings.mtConnect, count: Number(event.target.value) } })} /></Field></div><Field label="HTTP User-Agent" hint="HTTP client name sent to the agent in requests. Keep SparkStudio/1.0 unless your agent or proxy requires another valid User-Agent."><input value={settings.mtConnect?.userAgent ?? "SparkStudio/1.0"} onChange={event => patch({ mtConnect: { ...settings.mtConnect, userAgent: event.target.value } })} /></Field><p className="muted">Conditions, DATA_SET and TABLE values are reduced before delivery. Transient events may be coalesced; this source is not a lossless event journal.</p></section>}
    {type === "i3x" && <section className="source-mapping-section" aria-label="i3X subscription and reconciliation" hidden={section !== undefined && section !== "acquisition"}><h3 className="form-section-title">i3X reconciliation</h3><p className="source-mapping-help">These settings apply to Subscription / stream. Polling uses the current-value interval above.</p><label className="checkbox-field"><input type="checkbox" checked={settings.i3x?.preferStream !== false} onChange={event => patch({ i3x: { ...settings.i3x, preferStream: event.target.checked } })} /><span>Prefer advertised SSE, with sync fallback</span></label><p className="source-mapping-help">SSE means server-sent events: the service sends subscription updates over an open HTTP stream. Keep checked to try advertised SSE; sync requests are used if SSE is not advertised or returns 501 Not Implemented. Uncheck to use sync directly. Other stream failures enter recovery and appear in Diagnostics.</p><div className="form-two-col"><Field label="Reconcile current state every (seconds)" hint="Subscriptions only. Fetch authoritative current values periodically to repair missed or drifting updates, even while connected. Start with 30 seconds; allowed range is 5–300 seconds. This is separate from the sync-request interval."><input type="number" min={5} max={300} value={settings.i3x?.reconciliationSeconds ?? 30} onChange={event => patch({ i3x: { ...settings.i3x, reconciliationSeconds: Number(event.target.value) } })} /></Field><Field label="Client identity" hint="Name identifying this gateway's i3X subscription client, not an element ID or tag path. Leave blank to generate and retain an identity on first save; normally keep the saved value."><input value={settings.i3x?.clientId ?? ""} onChange={event => patch({ i3x: { ...settings.i3x, clientId: event.target.value || null } })} /></Field></div><p className="muted">Element IDs remain opaque; structured selectors are separate JSON pointers. Subscriptions are best effort, with visible recovery and data-loss diagnostics.</p></section>}
    {type === "mqtt" && <MqttFields settings={settings} onChange={onChange} savedMappingIds={savedMappingIds} section={section} />}
    <details hidden={section !== undefined && section !== "advanced"} open={section === "advanced" ? true : undefined}><summary>Effective limits and timeouts</summary><p className="muted">Advanced settings: keep the defaults for initial setup. Defaults are bounded by the gateway resource profile. Smaller limits can reject oversized documents or imports; Test and Diagnostics report the effective settings.</p><div className="form-two-col">{(Object.keys(defaults) as (keyof SourceLimits)[]).filter(key => type === "mqtt" || !["packetBytes", "payloadBytes", "scriptTimeoutMs", "scriptResultBytes", "scriptResultDepth", "scriptResultMembers", "scriptResultLeaves", "workerCount"].includes(key)).map(key => <Field key={key} label={limitLabels[key]} hint={type === "mqtt" ? undefined : type === "mtconnect" && (key === "queueBytes" || key === "queueCount") ? "Common ingress setting used by other source clients; it does not control MTConnect document buffering. Keep the default here and use document, decode and state limits for MTConnect." : type === "i3x" && key === "documentBytes" ? "Maximum JSON bytes in one response or event, also bounded by ingress limits for subscriptions. 1048576 is 1 MiB. Decode working bytes must be at least 8 times this value; keep the defaults initially." : type === "i3x" && key === "decodeBytes" ? "Temporary decode-memory budget, separate from saved values. Must be at least 8 times the document-byte limit to admit one response; the default 33554432 (32 MiB) admits four concurrent 1 MiB responses." : limitHints[key]}><input type="number" min={1} step={1} value={settings.limits?.[key] ?? defaults[key]} onChange={event => patch({ limits: { ...settings.limits, [key]: Number(event.target.value) } })} /></Field>)}</div></details>
  </div>;
}

function MqttFields({ settings, onChange, savedMappingIds, section }: { settings: SourceSettings; onChange: (source: SourceSettings) => void; savedMappingIds: string[]; section?: ConnectionEditorSection }) {
  const mqtt = settings.mqtt ?? {}, mappings = mqtt.mappings ?? [];
  const [selected, setSelected] = useState("");
  const mapping = mappings.find(item => item.id === selected);
  const patch = (next: Partial<NonNullable<SourceSettings["mqtt"]>>) => onChange({ ...settings, mqtt: { ...mqtt, ...next } });
  const editMapping = (next: Partial<SourceMqttMapping>) => patch({ mappings: mappings.map(item => item.id === selected ? { ...item, ...next } : item) });
  return <><div className="source-field-section" hidden={section !== undefined && section !== "connection"}><h3 className="form-section-title">Broker session</h3><div className="form-two-col"><Field label="Protocol"><select value={mqtt.protocolVersion ?? "5"} onChange={event => patch({ protocolVersion: event.target.value as "5" | "3.1.1" })}><option value="5">MQTT 5</option><option value="3.1.1">MQTT 3.1.1</option></select></Field><Field label="Transport"><select value={mqtt.transport ?? "tcp"} onChange={event => patch({ transport: event.target.value as "tcp" | "tls" | "websocket" })}><option value="tcp">TCP</option><option value="tls">TLS</option><option value="websocket">WebSocket</option></select></Field><Field label="Client identity" hint="Generated and persisted on first save when blank."><input value={mqtt.clientId ?? ""} onChange={event => patch({ clientId: event.target.value || null })} /></Field><Field label="Keep alive (seconds)"><input type="number" min={5} max={300} value={mqtt.keepAliveSeconds ?? 30} onChange={event => patch({ keepAliveSeconds: Number(event.target.value) })} /></Field><Field label="Session expiry (seconds)"><input type="number" min={0} max={3600} value={mqtt.sessionExpirySeconds ?? 0} onChange={event => patch({ sessionExpirySeconds: Number(event.target.value) })} /></Field><label className="checkbox-field"><input type="checkbox" checked={mqtt.cleanStart !== false} onChange={event => patch({ cleanStart: event.target.checked })} /><span>Clean start</span></label></div>
    </div><div className="source-field-section" hidden={section !== undefined && section !== "mappings"}>
    <div className="source-section-actions"><h3>Topic mappings</h3><button className="button" onClick={() => { const key = id("mapping"); patch({ mappings: [...mappings, { id: key, topicFilter: "plant/#", root: "[default]MQTT", tags: "review", payload: "scalar", retained: "uncertain", structuredUpdates: "snapshot", shape: "scalar", ordering: "receipt", enabled: true, qos: 0 }] }); setSelected(key); }}>Add mapping</button></div>
    <div className="source-mapping-guide"><p>A mapping chooses which MQTT topics to receive, how to read their message values, and where those values become tags. Start with <strong>Observe and review import</strong> to choose the tags before creating them.</p><a href="https://sparkstudiox.com/docs/mqtt-setup/#topic-mapping-field-reference" target="_blank" rel="noreferrer">MQTT setup and field guide ↗</a></div>
    <p className="muted">Review and automatic modes observe enabled filters with zero saved tags. Raw topics and selectors retain their identities. Use broker credentials limited to subscribe/read.</p>
    <Field label="Mapping" hint="Choose the topic rule to edit. Each mapping can use a different filter, payload format and tag folder."><select value={selected} onChange={event => setSelected(event.target.value)}><option value="">Choose a mapping…</option>{mappings.map(item => <option key={item.id} value={item.id}>{item.topicFilter} · {item.tags}{item.enabled === false ? " · disabled" : ""}</option>)}</select></Field>
    {mapping && <div className="tag-mapping-form">
      <div className="source-section-actions"><strong>{mapping.id}</strong><button className="button danger small" onClick={() => { patch({ mappings: mappings.filter(item => item.id !== selected) }); setSelected(""); }}>Remove mapping</button></div>
      <label className="checkbox-field"><input type="checkbox" checked={mapping.enabled !== false} onChange={event => editMapping({ enabled: event.target.checked })} /><span>Mapping enabled</span></label>
      <p className="source-mapping-help">Receive and process this rule's matching topics. Turning it off pauses this mapping; saved readings remain with Bad_Disabled quality.</p>
      <section className="source-mapping-section" aria-label="Topics and tag creation">
        <h4>1. Choose topics and tag creation</h4>
        <div className="form-two-col">
          <Field label="Mapping ID" hint="Stable name for this rule and its saved points, not an MQTT topic. Keep the generated ID, or choose one before first save; it is fixed afterward."><input readOnly={savedMappingIds.includes(mapping.id)} value={mapping.id} onChange={event => { editMapping({ id: event.target.value }); setSelected(event.target.value); }} /></Field>
          <Field label="Topic filter" hint="Topics to receive: plant/# matches plant and everything below it; plant/+/temperature matches one level between plant and temperature. Use an exact topic for Explicit saved points."><input value={mapping.topicFilter} onChange={event => editMapping({ topicFilter: event.target.value })} /></Field>
          <Field label="Owned root" hint="Starting tag folder, such as [default]MQTT. Review mode suggests paths here; Automatic reserves this folder for its generated tags. Choose an unused folder for Automatic."><input value={mapping.root} onChange={event => editMapping({ root: event.target.value })} /></Field>
          <Field label="Tag creation" hint={mapping.tags === "explicit" ? "Only read points you explicitly save in the connection. This mode requires an exact topic filter; create tags for those points in Tags." : mapping.tags === "automatic" ? "Create and maintain tags as valid messages arrive. This mapping owns their folder and types; removing a generated tag suppresses its rediscovery." : "Observe messages without creating tags. Browse the observed catalog, select values, then preview and apply their point-and-tag import."}><select value={mapping.tags} onChange={event => editMapping({ tags: event.target.value as SourceMqttMapping["tags"], ...(event.target.value === "explicit" ? { shape: "scalar" } : {}) })}><option value="explicit">Explicit saved points</option><option value="review">Observe and review import</option><option value="automatic">Automatic (opt in)</option></select></Field>
          <Field label="Strip topic levels" hint="Remove leading topic folders from suggested tag paths only. With root [default]MQTT, stripping 1 from plant/line1/temp gives [default]MQTT/line1/temp. The subscribed topic stays unchanged; keep at least one level."><input type="number" min={0} max={64} value={mapping.stripLevels ?? 0} onChange={event => editMapping({ stripLevels: Number(event.target.value) })} /></Field>
        </div>
      </section>
      <section className="source-mapping-section" aria-label="Message values">
        <h4>2. Turn messages into values</h4>
        <div className="form-two-col">
          <Field label="Payload" hint={mapping.payload === "script" ? "Extract a value from a message using the expression below. For JSON such as {\"value\":23.5}, json(payload).value returns 23.5. Test it in Mapping test before saving." : "Read one number, Boolean or text value, such as 23.5, true or ready. A JSON object or array needs Scriban extraction instead."}><select value={mapping.payload} onChange={event => editMapping({ payload: event.target.value as "scalar" | "script", ...(event.target.value === "script" && !mapping.script ? { script: "json(payload).value" } : {}) })}><option value="scalar">UTF-8 scalar</option><option value="script">Scriban extraction</option></select></Field>
          <Field label="Declared type" hint={mapping.dataType ? "Convert each result to this type; incompatible values get bad quality. Double is a useful choice for sensors that can send both whole numbers and decimals." : "Use the first accepted value's type for each topic or child, then keep that type. A first value of 21 infers Int64; choose Double if later values may be 21.5."}><select value={mapping.dataType ?? ""} onChange={event => editMapping({ dataType: event.target.value ? event.target.value as TagWriteDataType : null })}><option value="">Infer once and lock</option>{scalarTypes.map(type => <option key={type}>{type}</option>)}</select></Field>
          <Field label="Result shape" hint="Scalar gives one value per topic. Declared / discovered structure expands an extracted object or array into separate child values; review those children before importing."><select value={mapping.shape ?? "scalar"} onChange={event => editMapping({ shape: event.target.value as "scalar" | "structure" })}><option value="scalar">Scalar</option><option value="structure" disabled={mapping.tags === "explicit"}>Declared / discovered structure</option></select></Field>
          <Field label="Structured updates" hint="For structured results only: Snapshot clears previously saved children missing from the next result to Bad_NoData. Patch keeps missing children's previous values. An explicit null skips an update in either mode."><select value={mapping.structuredUpdates ?? "snapshot"} onChange={event => editMapping({ structuredUpdates: event.target.value as "snapshot" | "patch" })}><option value="snapshot">Snapshot · omitted leaves become NoData</option><option value="patch">Patch · omitted leaves stay unchanged</option></select></Field>
        </div>
        {mapping.payload === "script" && <Field label="Extraction expression" hint={'For {"value":23.5}, use json(payload).value. Return one value for Scalar or an object/array for Structure. Missing fields fail unless guarded; null skips delivery.'}><textarea rows={6} spellCheck={false} value={mapping.script ?? "json(payload).value"} onChange={event => editMapping({ script: event.target.value })} /></Field>}
        <Field label="Source timestamp expression (optional)" hint="Publisher's observation time, separate from gateway arrival time. For a JSON message with an ISO-8601 UTC timestamp, use json(payload).timestamp. Leave blank if the message has no timestamp; this does not change message ordering."><textarea rows={2} spellCheck={false} value={mapping.timestampExpression ?? ""} onChange={event => editMapping({ timestampExpression: event.target.value || null })} /></Field>
      </section>
      <section className="source-mapping-section" aria-label="Delivery and cleanup">
        <h4>3. Handle delivery and cleanup</h4>
        <div className="form-two-col">
          <Field label="Retained messages" hint="A broker may replay its saved value when you subscribe. Cached accepts it as Uncertain_Retained; Treat as current trusts it as Good; Ignore skips it. Cached replay does not prove fresh publisher traffic."><select value={mapping.retained ?? "uncertain"} onChange={event => editMapping({ retained: event.target.value as SourceMqttMapping["retained"] })}><option value="uncertain">Cached · Uncertain_Retained</option><option value="good">Treat as current · Good</option><option value="ignore">Ignore</option></select></Field>
          <Field label="QoS" hint="Requested subscription delivery level: 0 has no delivery acknowledgment; 1 acknowledges delivery but may repeat a message. Start with 0 unless your broker/publisher needs 1."><select value={mapping.qos ?? 0} onChange={event => editMapping({ qos: Number(event.target.value) })}><option value={0}>0</option><option value={1}>1</option></select></Field>
          <Field label="Freshness deadline (ms; 0 disables)" hint="How long a value may go without an accepted fresh update before becoming Uncertain_Stale. 5000 means 5 seconds; 0 disables the check. The previous value remains visible with its quality."><input type="number" min={0} max={86400000} value={mapping.staleAfterMs ?? 0} onChange={event => editMapping({ staleAfterMs: Number(event.target.value) })} /></Field>
          <Field label="Application ordering" hint="Which message may replace the current value. Keep Arrival order unless the publisher provides a sequence or timestamp plus a run ID; those modes skip duplicate or older values within that run."><select value={mapping.ordering ?? "receipt"} onChange={event => editMapping({ ordering: event.target.value as SourceMqttMapping["ordering"] })}><option value="receipt">Arrival order</option><option value="sequence">Publisher sequence and epoch</option><option value="timestamp">Qualified timestamp and epoch</option></select></Field>
          <Field label="Mapping tag cap" hint="Automatic mode only: maximum active tags this mapping may own. A proposed batch exceeding the cap is rejected together. This does not limit the review catalog; start with a cap sized for your expected topics and children."><input type="number" min={1} max={10000} value={mapping.maximumTags ?? 10000} onChange={event => editMapping({ maximumTags: Number(event.target.value) })} /></Field>
          <Field label="Prune after (seconds; 0 disables)" hint="Automatic mode only: remove unreferenced generated tags after this much healthy time without a value. 3600 means 1 hour; 0 disables cleanup. Disconnects do not count as healthy absence, and referenced tags are protected."><input type="number" min={0} max={31536000} value={mapping.pruneAfterSeconds ?? 0} onChange={event => editMapping({ pruneAfterSeconds: Number(event.target.value) })} /></Field>
        </div>
        {mapping.ordering && mapping.ordering !== "receipt" && <>
          <Field label={mapping.ordering === "timestamp" ? "Ordering timestamp expression" : "Publisher sequence expression"} hint={mapping.ordering === "timestamp" ? "Extract the publisher's ISO-8601 timestamp, for example json(payload).timestamp. Equal or older timestamps in the same publisher run are skipped." : "Extract an increasing nonnegative whole-number sequence, for example json(payload).sequence. Equal or lower numbers in the same publisher run are skipped."}><textarea rows={2} value={mapping.sequenceExpression ?? ""} onChange={event => editMapping({ sequenceExpression: event.target.value || null })} /></Field>
          <Field label="Publisher epoch expression" hint="Extract the publisher's run/session ID, for example json(payload).bootId. It must change when the sequence or ordering clock restarts, so new data can be accepted after a reset."><textarea rows={2} value={mapping.epochExpression ?? ""} onChange={event => editMapping({ epochExpression: event.target.value || null })} /></Field>
        </>}
      </section>
      {mapping.tags === "automatic" && <p role="status">Automatic mode owns definitions beneath this root, persists locked types and rejects collisions atomically. Existing references can block pruning or migration. Review the namespace before saving.</p>}
    </div>}
  </div></>;
}

export function SourceConnectionTools({ connection, saved, disabled, onChange, onImported, notify, section }: { connection: Connection; saved: boolean; disabled: boolean; onChange: (source: SourceSettings) => void; onImported: (connection: Connection) => void; notify: (message: string, error?: boolean) => void; section?: ConnectionEditorSection }) {
  const settings = connection.source!, points = settings.points ?? [];
  const [busy, setBusy] = useState(false), [error, setError] = useState("");
  const [mapText, setMapText] = useState(""), [mapOpen, setMapOpen] = useState(false), [mapPreview, setMapPreview] = useState<SourcePoint[] | null>(null);
  const [pointDraft, setPointDraft] = useState<SourcePoint | null>(null), [editingPointId, setEditingPointId] = useState<string | null>(null);
  const [entries, setEntries] = useState<SourceBrowseEntry[]>([]), [token, setToken] = useState<string | null>(null), [truncated, setTruncated] = useState(false);
  const [trail, setTrail] = useState<{ address: string; name: string }[]>([]), [selected, setSelected] = useState<Record<string, SourceImportPoint>>({});
  const selectedEntries = useRef(new Map<string, SourceBrowseEntry>());
  const { user } = useAuth();
  const [root, setRoot] = useState(`[default]Sources/${connection.id}`), [preview, setPreview] = useState<SourceImportPreview | null>(null);
  const [values, setValues] = useState<Record<string, SourceReadValue>>({}), [owned, setOwned] = useState<SourceOwnedPoint[]>([]), [ownedLoaded, setOwnedLoaded] = useState(false);
  const [scriptMapping, setScriptMapping] = useState(""), [topic, setTopic] = useState("plant/example"), [payload, setPayload] = useState("42"), [retained, setRetained] = useState(false), [scriptResult, setScriptResult] = useState<SourceScriptTestResult | null>(null);
  const generation = useRef(0), mounted = useRef(false), fileGeneration = useRef(0), scriptGeneration = useRef(0);
  const configurationKey = JSON.stringify(settings);
  useEffect(() => { mounted.current = true; return () => { mounted.current = false; generation.current++; }; }, []);
  useEffect(() => { generation.current++; fileGeneration.current++; setBusy(false); setEntries([]); setToken(null); setTrail([]); setSelected({}); setPreview(null); setValues({}); setScriptResult(null); setError(""); setMapPreview(null); }, [connection.id, connection.revision, connection.enabled, disabled, saved, configurationKey]);
  const available = saved && connection.enabled !== false && !disabled;
  const ownershipAvailable = connection.revision !== undefined && !disabled;
  const ownedIds = new Set([...owned.map(point => point.pointId), ...points.filter(point => point.owned).map(point => point.id)]);
  useEffect(() => { setOwned([]); setOwnedLoaded(false); }, [connection.id, connection.revision]);
  const testAvailable = connection.revision !== undefined && connection.enabled !== false && !disabled;
  const route = `/connections/${encodeURIComponent(connection.id)}/source`;
  async function run(action: (current: () => boolean) => Promise<void>) {
    const stamp = generation.current; setBusy(true); setError("");
    const current = () => mounted.current && stamp === generation.current;
    try { await action(current); } catch (reason) { if (current()) { setPreview(null); setError(errorMessage(reason)); } }
    finally { if (current()) setBusy(false); }
  }
  async function browse(parent: string | null = null, name = "Root", next = false, history?: typeof trail) {
    if (!available) return;
    await run(async current => {
      const result = await api<SourceBrowsePage>(`${route}/browse`, "POST", { parent, pageSize: 100, revision: connection.revision ?? 0, continuationToken: next ? token : undefined });
      if (!current()) return;
      setEntries(sourceBrowseRows(next ? [...entries, ...result.entries] : result.entries)); setToken(result.continuationToken ?? null); setTruncated(result.truncated);
      if (!next) setTrail(history ?? (parent ? [...trail, { address: parent, name }] : []));
    });
  }
  function toggle(entry: SourceBrowseEntry, checked: boolean) {
    setPreview(null); const key = sourceEntryKey(entry);
    if (checked) selectedEntries.current.set(key, entry); else selectedEntries.current.delete(key);
    setSelected(old => { const next = { ...old }; if (checked) next[key] = sourceImportPoint(entry, root); else delete next[key]; return next; });
  }
  async function importDevice(entry: SourceBrowseEntry) {
    if (!available) return;
    await run(async current => {
      let continuation: string | null | undefined, catalog: SourceBrowseEntry[] = [];
      do { const page = await api<SourceBrowsePage>(`${route}/browse`, "POST", { parent: entry.address, revision: connection.revision ?? 0, pageSize: 500, continuationToken: continuation }); if (!current()) return;
        catalog = [...catalog, ...page.entries]; continuation = page.continuationToken;
        if (catalog.length > 1000) throw new Error("This device exceeds the 1,000-point reviewed batch limit. Browse it and import smaller selections.");
        if (page.truncated) throw new Error("The device catalog was truncated; import visible selections after reviewing its diagnostics.");
      } while (continuation);
      for (const item of catalog.filter(item => item.isVariable)) selectedEntries.current.set(sourceEntryKey(item), item);
      setSelected(old => ({ ...old, ...Object.fromEntries(catalog.filter(item => item.isVariable).map(item => [sourceEntryKey(item), sourceImportPoint(item, root)])) })); setPreview(null);
    });
  }
  const requested = Object.values(selected);
  async function createType() {
    await run(async current => {
      const configured = await api<TagDefinition[]>("/tag-engineering/definitions");
      const catalog = Object.entries(selected).map(([key, point]) => selectedEntries.current.get(key) || { ...point, isVariable: true });
      let sourceConnection = connection;
      if (connection.type === "mqtt") {
        const result = await api<SourceOwnedPoint[] | { leaves?: SourceOwnedPoint[]; points?: SourceOwnedPoint[]; items?: SourceOwnedPoint[] }>(`${route}/ownership`);
        const leaves = Array.isArray(result) ? result : result.leaves ?? result.points ?? result.items ?? [];
        sourceConnection = { ...connection, source: { ...settings, points: [...points, ...leaves.filter(point => !point.suppressed && !point.pruned).map(point => ({ id: point.pointId, name: point.path, address: point.address, selector: point.selector, mappingId: point.mappingId, dataType: scalarTypes.find(type => type === point.dataType) || "String", writable: false as const }))] } };
      }
      if (current() && user) openModelDraft({ definition: modelFromSource(sourceConnection, catalog, configured), origin: "source" }, user.id);
    });
  }
  async function reviewImport() { if (!available || !requested.length) return; await run(async current => { const result = await api<SourceImportPreview>(`${route}/import/preview`, "POST", { revision: connection.revision ?? 0, points: requested }); if (current()) setPreview(result); }); }
  async function applyImport() { if (!available || !preview) return; await run(async current => { const result = await api<{ imported: number; connection: Connection }>(`${route}/import/apply`, "POST", { revision: connection.revision ?? 0, points: requested, previewToken: preview.previewToken }); if (!current()) return; notify(`${result.imported} source points and tags imported atomically.`); onImported(result.connection); }); }
  async function read(ids: string[]) { if (!available || !ids.length) return; await run(async current => { const result = await api<{ values: SourceReadValue[] }>(`${route}/read`, "POST", { revision: connection.revision ?? 0, nodeIds: ids.slice(0, 1000) }); if (current()) setValues(old => ({ ...old, ...Object.fromEntries(result.values.map(value => [value.pointId, value])) })); }); }
  async function ownership() { if (!ownershipAvailable) return; await run(async current => { const result = await api<SourceOwnedPoint[] | { leaves?: SourceOwnedPoint[]; points?: SourceOwnedPoint[]; items?: SourceOwnedPoint[] }>(`${route}/ownership`); if (current()) { setOwned(Array.isArray(result) ? result : result.leaves ?? result.points ?? result.items ?? []); setOwnedLoaded(true); } }); }
  async function loadMapFile(file?: File) {
    const stamp = ++fileGeneration.current, operation = generation.current;
    const current = () => mounted.current && stamp === fileGeneration.current && operation === generation.current;
    setMapPreview(null);
    if (!file) return;
    if (file.size > 2 * 1024 * 1024) { setError("Source point map file exceeds 2 MiB."); return; }
    try { const contents = await file.text(); if (current()) { setMapText(contents); setMapPreview(null); setError(""); } }
    catch (reason) { if (current()) setError(errorMessage(reason)); }
  }
  function applyMap() { if (!mapPreview) return; const errors = validateSourcePoints(mapPreview); if (errors.length) { setError(errors.join("\n")); return; } onChange({ ...settings, points: [...mapPreview, ...points.filter(point => ownedIds.has(point.id))] }); setMapPreview(null); setMapOpen(false); }
  return <div className="source-connection-tools" inert={disabled}>
    <section className="browse-section" hidden={section !== undefined && section !== "points"}><div className="browse-section-heading"><div><h3>Saved source points</h3><p>Saved points identify values the connection can read. Add point and JSON editing change the draft only: save the connection, then create their tags in Tags. Browse import below creates points and tags together. These sources never allow writes.</p></div><div className="editor-actions"><button className="button" disabled={busy} onClick={() => { setEditingPointId(null); setPointDraft({ id: id("point"), name: "New point", address: "", dataType: "String", writable: false }); }}>Add point</button><button className="button" disabled={busy} onClick={() => { fileGeneration.current++; setMapText(JSON.stringify(points.filter(point => !ownedIds.has(point.id)), null, 2)); setMapOpen(!mapOpen); setMapPreview(null); }}>Import / edit JSON</button><button className="button" disabled={!available || busy || !points.length} onClick={() => void read(points.slice(0, 256).map(point => point.id))}>Read first 256 points</button></div></div>
      {!points.length && <p className="panel-empty">{connection.type === "mqtt" ? "No saved points. MQTT review/automatic discovery starts from its filters without a dummy tag." : "No saved points. Save and test the connection, then browse the source below to select values and import their tags."}</p>}
      {!!points.length && <div className="data-table-wrap"><table className="data-table"><thead><tr><th>Point</th><th>Address / selector</th><th>Type</th><th>Current value</th><th>Actions</th></tr></thead><tbody>{points.slice(0, 200).map(point => <tr key={point.id}><td>{point.name}<small>{point.id}{ownedIds.has(point.id) ? " · generated / owned" : ""}</small></td><td><code>{point.address}</code>{point.selector && <small>{point.selector}</small>}</td><td>{point.dataType} · read only</td><td>{values[point.id] && <><span>{displayValue(values[point.id].value)}</span><small>{values[point.id].quality} · Source {values[point.id].sourceTimestamp ?? "unknown"} · Receipt {values[point.id].receiptTimestamp ?? "unknown"}</small></>}</td><td><div className="editor-actions"><button className="button small" disabled={busy || !available} onClick={() => void read([point.id])}>Read</button><button className="button small" disabled={busy || ownedIds.has(point.id)} title={ownedIds.has(point.id) ? "Manage generated definitions in Tags and Ownership." : undefined} onClick={() => { setEditingPointId(point.id); setPointDraft({ ...point, writable: false }); }}>Edit</button><button className="button danger small" disabled={busy || ownedIds.has(point.id)} title={ownedIds.has(point.id) ? "Remove generated definitions in Tags to persist suppression." : undefined} onClick={() => onChange({ ...settings, points: points.filter(item => item.id !== point.id) })}>Remove</button></div></td></tr>)}</tbody></table></div>}
      {points.length > 200 && <p>Showing the first 200 of {points.length} saved points. JSON editing includes the complete authored map; generated points are managed through Tags and Ownership.</p>}
      {ownedIds.size > 0 && <p className="muted">Generated definitions are managed in Tags and Ownership. Their identities and locked types remain with the source; JSON editing changes authored points only.</p>}
      {pointDraft && <div className="tag-mapping-form"><div className="form-two-col"><Field label="Point ID" hint="Stable local identity used by tag references, not the source address. Keep the generated ID or choose one before saving; saved IDs are fixed."><input value={pointDraft.id} readOnly={editingPointId !== null} onChange={event => setPointDraft({ ...pointDraft, id: event.target.value })} /></Field><Field label="Point name" hint="Friendly display name, such as Spindle speed or Running. It does not change the source address or automatically create a tag."><input value={pointDraft.name} onChange={event => setPointDraft({ ...pointDraft, name: event.target.value })} /></Field><Field label="Raw address" hint={connection.type === "i3x" ? "Exact element ID from Browse source, such as urn:line1:machine#state. Preserve every character, including #; do not append a selector or substitute a tag path." : connection.type === "mtconnect" ? "Exact address from Browse source, identifying the device UUID and data-item ID. Copy the catalog address rather than the display name or a gateway tag path." : "Exact MQTT topic for this saved value. Keep any structured selector separate; this is not the gateway tag path."}><input value={pointDraft.address} onChange={event => setPointDraft({ ...pointDraft, address: event.target.value })} /></Field><Field label="Selector (separate from address)" hint={connection.type === "mtconnect" ? "Leave blank for a scalar. Conditions expose level, nativeCode, nativeSeverity, message and active; 3D values expose x, y and z. A DATA_SET key uses /toolCount; a TABLE member uses /row1/temperature. Prefer the browsed selector." : "Leave blank for a scalar value. For a structured value, use a JSON pointer such as /running or /motor/speed. Escape / inside a member name as ~1 and ~ as ~0; keep the raw address unchanged."}><input value={pointDraft.selector ?? ""} onChange={event => setPointDraft({ ...pointDraft, selector: event.target.value || null })} /></Field><Field label="Data type" hint="Type of the selected value, not the whole device: Boolean for true/false, Double for decimal measurements, Int64 for whole-number counters, String for text or whole structured JSON. Browse suggests a type; incompatible values receive bad quality."><select value={pointDraft.dataType} onChange={event => setPointDraft({ ...pointDraft, dataType: event.target.value as TagWriteDataType })}>{scalarTypes.map(type => <option key={type}>{type}</option>)}</select></Field>{connection.type === "mqtt" && <Field label="Mapping"><select value={pointDraft.mappingId ?? ""} onChange={event => setPointDraft({ ...pointDraft, mappingId: event.target.value || null })}><option value="">Choose a mapping…</option>{settings.mqtt?.mappings?.map(mapping => <option key={mapping.id} value={mapping.id}>{mapping.topicFilter}</option>)}</select></Field>}</div><div className="editor-actions"><button className="button" onClick={() => setPointDraft(null)}>Cancel point</button><button className="button primary" onClick={() => { const next = editingPointId ? points.map(point => point.id === editingPointId ? pointDraft : point) : [...points, pointDraft]; const errors = validateSourcePoints(next); if (errors.length) setError(errors.join("\n")); else { onChange({ ...settings, points: next }); setPointDraft(null); } }}>Apply point to draft</button></div></div>}
      {mapOpen && <div className="tag-mapping-form"><Field label="Load source map file" hint="Load a JSON file of point definitions into the editor, up to 2 MiB. Loading does not save points or create tags; validate, apply to draft, then save the connection."><input type="file" accept=".json,application/json" onChange={event => { void loadMapFile(event.target.files?.[0]); event.target.value = ""; }} /></Field><Field label="Source points JSON" hint="Array of id, name, address, dataType and optional selector/mappingId. Writable must be false. Applying replaces the authored point-map draft; save the connection, then create tags in Tags."><textarea rows={10} spellCheck={false} value={mapText} onChange={event => { fileGeneration.current++; setMapText(event.target.value); setMapPreview(null); }} /></Field><button className="button" onClick={() => { try { setMapPreview(parseSourceMap(mapText)); setError(""); } catch (reason) { setError(errorMessage(reason)); } }}>Validate map</button>{mapPreview && <><p>{mapPreview.length} read-only points after apply. Saved references can block removal or retyping.</p><button className="button primary" onClick={applyMap}>Apply reviewed map to draft</button></>}</div>}
    </section>
    <section className="browse-section" hidden={section !== undefined && section !== "browse"}><div className="browse-section-heading"><div><h3>{connection.type === "mqtt" ? "Observed topic catalog" : "Browse source"}</h3><p>Browse metadata, select values, then preview and apply to save their points and create tags together. Choose each selected value's type and tag path before previewing; Apply does not require another Save connection.</p></div><button className="button" disabled={!available || busy} onClick={() => void browse()}>{busy ? "Working…" : "Browse / refresh"}</button></div>{!available && <p className="muted">Save and enable the connection to browse, read or import.</p>}
      {trail.length > 0 && <nav className="browse-breadcrumb"><button onClick={() => void browse()}>Root</button>{trail.map((item, index) => <button key={`${item.address}:${index}`} disabled={busy} onClick={() => void browse(item.address, item.name, false, trail.slice(0, index + 1))}>{item.name}</button>)}</nav>}
      <Field label="Import root" hint="Starting gateway tag folder for newly selected values, such as [default]Machines/Mill01 or [default]I3XDemo. Choose it before selecting points. Changing it does not rewrite paths already selected; edit those Tag path cells or clear and reselect."><input value={root} onChange={event => { setRoot(event.target.value); setPreview(null); }} /></Field>
      <div className="browse-list">{entries.map(entry => <div className="browse-node" key={`${sourceEntryKey(entry)}:${entry.isVariable}`}><label className="checkbox-field">{entry.isVariable ? <input aria-label={`Import ${entry.name}${entry.selector ? " " + entry.selector : ""}`} type="checkbox" checked={Boolean(selected[sourceEntryKey(entry)])} disabled={busy} onChange={event => toggle(entry, event.target.checked)} /> : <span>▸</span>}</label><div className="browse-node-name"><strong>{entry.name}</strong><code>{entry.address}</code><small>{entry.selector ? `${entry.selector} · ` : ""}{entry.dataType ?? "Folder"} · read only</small>{entry.metadata && <small>{[entry.metadata.category, entry.metadata.representation, entry.metadata.units, entry.metadata.nativeUnits].filter(Boolean).map(String).join(" · ")}</small>}</div><div className="editor-actions"><button className="button small" disabled={busy || !available} onClick={() => void browse(entry.address, entry.name)}>Browse children</button>{connection.type === "mtconnect" && !entry.isVariable && !trail.length && <button className="button small" disabled={busy || entry.metadata?.agent === true} title={entry.metadata?.agent === true ? "Agent is excluded from default device import. Browse and select its points explicitly if needed." : undefined} onClick={() => void importDevice(entry)}>Select device points</button>}</div></div>)}</div>
      {token && <button className="button" disabled={busy} onClick={() => void browse(trail.at(-1)?.address ?? null, trail.at(-1)?.name ?? "Root", true)}>Load next page</button>}{truncated && <p role="status">The source catalog is truncated at its configured limit. Review Diagnostics before importing.</p>}
      {entries.length > 0 && <button className="button" disabled={busy} onClick={() => { for (const entry of entries.filter(item => item.isVariable && item.metadata?.agent !== true)) toggle(entry, true); }}>Select displayed points</button>}
      {!!requested.length && <div className="tag-mapping-form"><div className="source-section-actions"><strong>{requested.length} selected points</strong><button className="button" onClick={() => { setSelected({}); setPreview(null); }}>Clear selection</button></div><div className="data-table-wrap"><table className="data-table"><thead><tr><th>Name / address</th><th>Type</th><th>Tag path</th><th /></tr></thead><tbody>{Object.entries(selected).slice(0, 1000).map(([key, point]) => <tr key={key}><td>{point.name}<small>{point.address}{point.selector ? ` · ${point.selector}` : ""}</small></td><td><select value={point.dataType} onChange={event => { setPreview(null); setSelected(old => ({ ...old, [key]: { ...point, dataType: event.target.value as TagWriteDataType } })); }}>{scalarTypes.map(type => <option key={type}>{type}</option>)}</select></td><td><input value={point.path} onChange={event => { setPreview(null); setSelected(old => ({ ...old, [key]: { ...point, path: event.target.value } })); }} /></td><td><button className="button small" onClick={() => { setPreview(null); setSelected(old => { const next = { ...old }; delete next[key]; return next; }); }}>Remove</button></td></tr>)}</tbody></table></div><div className="editor-actions"><button className="button" disabled={!available || busy || requested.length > 1000} onClick={() => void reviewImport()}>Preview point and tag import</button>{preview && <button className="button primary" disabled={busy || !available} onClick={() => void applyImport()}>Apply reviewed import</button>}</div>{requested.length > 1000 && <p role="alert">Import at most 1,000 points per reviewed transaction.</p>}{preview && <p role="status">{preview.points.length} points/tags proposed; {preview.totalTags} total tags after apply. All selected rows are included. Saving other configuration invalidates this preview.</p>}</div>}
    </section>
    {connection.type === "mqtt" && <>
      <section className="browse-section" hidden={section !== undefined && section !== "mapping-test"}><h3>Mapping test</h3><p>Evaluate one supplied payload without changing live values or definitions. Tests use the selected draft mapping; save a new connection once to enable this panel.</p><div className="form-two-col"><Field label="Test mapping"><select value={scriptMapping} onChange={event => { scriptGeneration.current++; setScriptMapping(event.target.value); setScriptResult(null); }}><option value="">Choose a mapping…</option>{settings.mqtt?.mappings?.map(mapping => <option value={mapping.id} key={mapping.id}>{mapping.topicFilter}</option>)}</select></Field><Field label="Topic"><input value={topic} onChange={event => { scriptGeneration.current++; setTopic(event.target.value); setScriptResult(null); }} /></Field></div><Field label="Test payload"><textarea rows={5} spellCheck={false} value={payload} onChange={event => { scriptGeneration.current++; setPayload(event.target.value); setScriptResult(null); }} /></Field><label className="checkbox-field"><input type="checkbox" checked={retained} onChange={event => { scriptGeneration.current++; setRetained(event.target.checked); setScriptResult(null); }} /><span>Retained message</span></label><button className="button" disabled={!testAvailable || busy || !scriptMapping} onClick={() => void run(async current => { const scriptStamp = scriptGeneration.current; const result = await api<SourceScriptTestResult>(`${route}/script/test`, "POST", { revision: connection.revision ?? 0, mappingId: scriptMapping, mapping: settings.mqtt?.mappings?.find(mapping => mapping.id === scriptMapping), topic, payload, retained }); if (current() && scriptStamp === scriptGeneration.current) setScriptResult(result); })}>Test mapping</button>{scriptResult !== null && <SourceScriptTestOutput result={scriptResult} />}</section>
      <section className="browse-section" hidden={section !== undefined && section !== "ownership"}><div className="browse-section-heading"><div><h3>Automatic ownership and suppression</h3><p>Removing a generated tag suppresses rediscovery. Pruning retains identity and locked types.</p></div><button className="button" disabled={!ownershipAvailable || busy} onClick={() => void ownership()}>Load ownership</button></div>{ownedLoaded && !owned.length && <p>No owned source definitions.</p>}{!!owned.length && <div className="data-table-wrap"><table className="data-table"><thead><tr><th>Path / identity</th><th>State</th><th>Type</th><th>Actions</th></tr></thead><tbody>{owned.slice(0, 1000).map(point => <tr key={point.pointId}><td>{point.path}<small>{point.address}{point.selector ? ` · ${point.selector}` : ""}</small></td><td>{point.suppressed ? "Suppressed" : point.pruned ? "Pruned" : "Owned"}</td><td>{point.dataType}</td><td>{point.suppressed && <button className="button small" disabled={busy} onClick={() => void run(async current => { await api(`${route}/suppression/clear`, "POST", { pointId: point.pointId, revision: connection.revision ?? 0 }); if (current()) { notify("Suppression cleared. Rediscovery is still subject to type, namespace and capacity checks."); setOwnedLoaded(false); setOwned([]); } })}>Allow rediscovery</button>}</td></tr>)}</tbody></table></div>}{owned.length > 1000 && <p>Showing the first 1,000 of {owned.length} owned records.</p>}</section>
    </>}
    <SourceModelDraftPanel section={section} count={requested.length} available={available} busy={busy} createType={createType} />
    {error && <p className="inline-error" role="alert" style={{ whiteSpace: "pre-wrap" }}>{error}</p>}
  </div>;
}
function SourceModelDraftPanel({ section, count, available, busy, createType }: { section?: ConnectionEditorSection; count: number; available: boolean; busy: boolean; createType: () => Promise<void> }) {
  return (section === undefined || section === "browse") && count > 0 ? <div className="model-actions"><button type="button" className="button" disabled={!available || busy || count > 128} onClick={() => void createType()}>Create model from selection</button><small>Reuse tags you have already imported. Opens Models so you can review the design before saving.</small></div> : null;
}
